    $ws = $wb.Worksheets.Item(1);
    $ws.Name = 'DangKyTamTru';
    $ws.Range('A1:M1').Merge();
    $ws.Range('A1').Value2 = 'DANH SACH DANG KY TAM TRU KY TUC XA';
    $ws.Range('A1').Font.Bold = $true;
    $ws.Range('A1').HorizontalAlignment = -4108;
    $ws.Range('A2').Value2 = '{Ngay}';
    $ws.Range('A3').Value2 = 'Tong so: {Tong so}';
    $headers = @('STT','Ma SV','Ho va ten','Ngay sinh','Gioi tinh','So CMND/CCCD','Lop','Noi thuong tru','Dia chi tam tru','So dien thoai','Ngay bat dau','Ngay ket thuc','Ghi chu');
    for ($i = 0; $i -lt $headers.Count; $i++) { $ws.Cells.Item(4, $i + 1).Value2 = $headers[$i]; $ws.Cells.Item(5, $i + 1).Value2 = $headers[$i]; }
    $ws.Range('A4:M4').Font.Bold = $true;
    $ws.Range('A4:M5').Borders.LineStyle = 1;
    $ws.Range('A4:M5').HorizontalAlignment = -4108;
    $ws.Columns.Item('A').ColumnWidth = 6;
    $ws.Columns.Item('B').ColumnWidth = 12;
    $ws.Columns.Item('C').ColumnWidth = 25;
    $ws.Columns.Item('D').ColumnWidth = 13;
    $ws.Columns.Item('E').ColumnWidth = 10;
    $ws.Columns.Item('F').ColumnWidth = 18;
    $ws.Columns.Item('G').ColumnWidth = 14;
    $ws.Columns.Item('H').ColumnWidth = 35;
    $ws.Columns.Item('I').ColumnWidth = 30;
    $ws.Columns.Item('J').ColumnWidth = 15;
    $ws.Columns.Item('K').ColumnWidth = 14;
    $ws.Columns.Item('L').ColumnWidth = 14;
    $ws.Columns.Item('M').ColumnWidth = 20;
    if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Force; }
    $wb.SaveAs($path, 51);
    $wb.Close($true);
    Write-Output ('created ' + $path);
}
catch {
    Write-Output ('excel-com-error: ' + $_.Exception.Message);
    if ($wb -ne $null) { $wb.Close($false); }
}
finally {
    if ($excel -ne $null) { $excel.Quit(); [System.Runtime.InteropServices.Marshal]::ReleaseComObject($excel) | Out-Null; }
}
Get-ChildItem -LiteralPath $dir -Force | ForEach-Object { '[' + $_.Name + '] ' + $_.Length }

