input.command:
$ErrorActionPreference='Stop'
$path = 'g:\0.DỰ ÁN\Z.WEB-CDN-QUYNHON\0.WINFORM\bin\Debug\MauExcel\KTX\DangKyTamTru.xls'
$excel = $null
$wb = $null
$ws = $null
try {
    $excel = New-Object -ComObject Excel.Application
    $excel.Visible = $false
    $excel.DisplayAlerts = $false
    $wb = $excel.Workbooks.Open($path)
    $ws = $wb.Worksheets.Item(1)
    $markers = @('Fullname','NgaySinh','GenderNam','GenderNu','QueQuan','DanToc','TonGiao','CCCD','NgayCapCCCD','NoiThuongTru','StartDateText','NoiTamTru','CanBoDangKy','Description')
    for ($i=0; $i -lt $markers.Length; $i++) {
        $ws.Cells.Item(5,$i+1).Value2 = $markers[$i]
    }
    $ws.Range('A5:N5').Font.Bold = $false
    $ws.Range('A5:N5').Font.ColorIndex = 1
    $ws.Range('A5:N5').HorizontalAlignment = -4108
    $ws.Range('A5:N5').VerticalAlignment = -4108
    $ws.Range('A5:N5').WrapText = $true
    $ws.Range('A5:N5').Borders.LineStyle = 1
    $ws.Range('A5:N5').Borders.Weight = 2
    $wb.Save()
    Write-Output "Updated template markers"
}
finally {
    if ($wb -ne $null) { $wb.Close($true) | Out-Null }
    if ($excel -ne $null) { $excel.Quit() | Out-Null }
    if ($ws -ne $null) { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($ws) | Out-Null }
    if ($wb -ne $null) { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($wb) | Out-Null }
    if ($excel -ne $null) { [System.Runtime.InteropServices.Marshal]::ReleaseComObject($excel) | Out-Null }
    [GC]::Collect()
    [GC]::WaitForPendingFinalizers()
}

